import java.math.BigInteger;

class Solution {
    public String abbreviateProduct(int left, int right) {
        String digits = product(left, right).toString();

        int end = digits.length();
        while (digits.charAt(end - 1) == '0') {
            end--;
        }

        int zeros = digits.length() - end;
        if (end <= 10) {
            return digits.substring(0, end) + "e" + zeros;
        }

        return digits.substring(0, 5) + "..."
                + digits.substring(end - 5, end) + "e" + zeros;
    }

    private BigInteger product(int left, int right) {
        if (right - left <= 3) {
            long value = 1;
            for (int i = left; i <= right; i++) {
                value *= i;
            }
            return BigInteger.valueOf(value);
        }

        int mid = left + (right - left) / 2;
        return product(left, mid).multiply(product(mid + 1, right));
    }
}

